#!/usr/bin/env python3
"""Round-7 gen3 corpus expansion: broad verified-competence families.

Every label is derived from first principles (worst-case bound of the written
program).  Symbol conventions follow the reviewed corpus: the first container
parameter is n, the second m; scalar parameters keep their own names; `x` is
the conventional scalar for digit/bit processing; graph families use V and E.
"""
import json, os
DATASETS = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "datasets")
FAMILIES = {}
def A(fam, sym, code, time, space, conf, tags):
    FAMILIES.setdefault(fam, []).append({"symbol": sym, "code": code, "time": time, "space": space, "confidence": conf, "tags": tags})
NV = 8

# ---------------------------------------------------------------- prefix sums
for v in range(NV):
    A("gen3-prefix", f"buildPrefix_{v}", f"vector<long long> buildPrefix_{v}(const vector<int>& a) {{ int n = a.size(); vector<long long> p(n + 1, 0); for (int i = 0; i < n; ++i) p[i + 1] = p[i] + a[i]; return p; }}", "O(n)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"rangeSumQueries_{v}", f"long long rangeSumQueries_{v}(const vector<int>& a, int q) {{ int n = a.size(); vector<long long> p(n + 1, 0); for (int i = 0; i < n; ++i) p[i + 1] = p[i] + a[i]; long long total = 0; for (int i = 0; i < q; ++i) {{ int l = i % n, r = (i + n / 2) % n; if (l > r) {{ int tmp = l; l = r; r = tmp; }} total += p[r + 1] - p[l]; }} return total; }}", "O(n + q)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"suffixSum_{v}", f"vector<long long> suffixSum_{v}(const vector<int>& a) {{ int n = a.size(); vector<long long> s(n + 1, 0); for (int i = n - 1; i >= 0; --i) s[i] = s[i + 1] + a[i]; return s; }}", "O(n)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"diffArray_{v}", f"vector<long long> diffArray_{v}(const vector<int>& a) {{ int n = a.size(); vector<long long> d(n, 0); if (n > 0) d[0] = a[0]; for (int i = 1; i < n; ++i) d[i] = a[i] - a[i - 1]; return d; }}", "O(n)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"rangeAddRestore_{v}", f"vector<long long> rangeAddRestore_{v}(int n, int q) {{ vector<long long> d(n + 1, 0); for (int i = 0; i < q; ++i) {{ int l = i % n, r = (i * 2 + 1) % n; if (l > r) {{ int tmp = l; l = r; r = tmp; }} d[l] += 1; if (r + 1 <= n) d[r + 1] -= 1; }} long long cur = 0; for (int i = 0; i < n; ++i) {{ cur += d[i]; d[i] = cur; }} return d; }}", "O(n + q)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"runningMax_{v}", f"int runningMax_{v}(const vector<int>& a) {{ int best = a[0]; for (int x : a) if (x > best) best = x; return best; }}", "O(n)", "O(1)", "exact", ["scan"])
    A("gen3-prefix", f"runningMin_{v}", f"int runningMin_{v}(const vector<int>& a) {{ int best = a[0]; for (int i = 0; i < (int)a.size(); ++i) if (a[i] < best) best = a[i]; return best; }}", "O(n)", "O(1)", "exact", ["scan"])
    A("gen3-prefix", f"prefixMax_{v}", f"vector<int> prefixMax_{v}(const vector<int>& a) {{ int n = a.size(); vector<int> p(n, 0); if (n > 0) p[0] = a[0]; for (int i = 1; i < n; ++i) {{ p[i] = p[i - 1]; if (a[i] > p[i]) p[i] = a[i]; }} return p; }}", "O(n)", "O(n)", "exact", ["prefix"])
    A("gen3-prefix", f"gridRowPrefix_{v}", f"vector<vector<int>> gridRowPrefix_{v}(const vector<vector<int>>& g) {{ int n = g.size(), m = g[0].size(); vector<vector<int>> p(n, vector<int>(m, 0)); for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) {{ p[i][j] = g[i][j]; if (j > 0) p[i][j] += p[i][j - 1]; }} return p; }}", "O(n m)", "O(n m)", "exact", ["prefix", "grid"])
    A("gen3-prefix", f"gridPrefix2d_{v}", f"vector<vector<long long>> gridPrefix2d_{v}(const vector<vector<int>>& g) {{ int n = g.size(), m = g[0].size(); vector<vector<long long>> p(n + 1, vector<long long>(m + 1, 0)); for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) p[i][j] = g[i - 1][j - 1] + p[i - 1][j] + p[i][j - 1] - p[i - 1][j - 1]; return p; }}", "O(n m)", "O(n m)", "exact", ["prefix", "grid"])
    A("gen3-prefix", f"gridRowSums_{v}", f"vector<int> gridRowSums_{v}(const vector<vector<int>>& g) {{ int n = g.size(), m = g[0].size(); vector<int> sums(n, 0); for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) sums[i] += g[i][j]; return sums; }}", "O(n m)", "O(n)", "exact", ["grid"])
    A("gen3-prefix", f"gridColSums_{v}", f"vector<int> gridColSums_{v}(const vector<vector<int>>& g) {{ int n = g.size(), m = g[0].size(); vector<int> sums(m, 0); for (int i = 0; i < n; ++i) for (int j = 0; j < m; ++j) sums[j] += g[i][j]; return sums; }}", "O(n m)", "O(m)", "exact", ["grid"])
    A("gen3-prefix", f"diagonalSum_{v}", f"long long diagonalSum_{v}(const vector<vector<int>>& g) {{ int n = g.size(); long long s = 0; for (int i = 0; i < n; ++i) s += g[i][i]; return s; }}", "O(n)", "O(1)", "exact", ["grid"])
    A("gen3-prefix", f"prefixCountQueries_{v}", f"int prefixCountQueries_{v}(const vector<int>& a, int q) {{ int n = a.size(); vector<int> p(n + 1, 0); for (int i = 0; i < n; ++i) p[i + 1] = p[i] + (a[i] % 2 == 0 ? 1 : 0); int total = 0; for (int i = 0; i < q; ++i) {{ int l = i % n, r = (i + n / 2) % n; if (l > r) {{ int tmp = l; l = r; r = tmp; }} total += p[r + 1] - p[l]; }} return total; }}", "O(n + q)", "O(n)", "exact", ["prefix"])

# ----------------------------------------------------- sliding window / two pointers
for v in range(NV):
    A("gen3-window", f"maxSumWindow_{v}", f"long long maxSumWindow_{v}(const vector<int>& a, int k) {{ int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; long long best = s; for (int i = k; i < n; ++i) {{ s += a[i] - a[i - k]; if (s > best) best = s; }} return best; }}", "O(n)", "O(1)", "estimated", ["window"])
    A("gen3-window", f"minSumWindow_{v}", f"long long minSumWindow_{v}(const vector<int>& a, int k) {{ int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; long long best = s; for (int i = k; i < n; ++i) {{ s += a[i] - a[i - k]; if (s < best) best = s; }} return best; }}", "O(n)", "O(1)", "estimated", ["window"])
    A("gen3-window", f"twoSumPair_{v}", f"pair<int, int> twoSumPair_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ int s = a[lo] + a[hi]; if (s == t) return make_pair(lo, hi); if (s < t) ++lo; else --hi; }} return make_pair(-1, -1); }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"isPalindromeVec_{v}", f"bool isPalindromeVec_{v}(const vector<int>& a) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ if (a[lo] != a[hi]) return false; ++lo; --hi; }} return true; }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"reverseInPlace_{v}", f"void reverseInPlace_{v}(vector<int>& a) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ int tmp = a[lo]; a[lo] = a[hi]; a[hi] = tmp; ++lo; --hi; }} }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"partitionEvenOdd_{v}", f"void partitionEvenOdd_{v}(vector<int>& a) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ if (a[lo] % 2 == 0) ++lo; else {{ int tmp = a[lo]; a[lo] = a[hi]; a[hi] = tmp; --hi; }} }} }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"removeDuplicates_{v}", f"int removeDuplicates_{v}(vector<int>& a) {{ int write = 0; for (int read = 0; read < (int)a.size(); ++read) {{ if (read == 0 || a[read] != a[read - 1]) a[write++] = a[read]; }} return write; }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"moveZeroes_{v}", f"void moveZeroes_{v}(vector<int>& a) {{ int write = 0; for (int read = 0; read < (int)a.size(); ++read) {{ if (a[read] != 0) {{ a[write] = a[read]; ++write; }} }} while (write < (int)a.size()) {{ a[write] = 0; ++write; }} }}", "O(n)", "O(1)", "exact", ["two-pointers"])
    A("gen3-window", f"mergeSortedVec_{v}", f"vector<int> mergeSortedVec_{v}(const vector<int>& a, const vector<int>& b) {{ vector<int> r; int i = 0, j = 0; while (i < (int)a.size() && j < (int)b.size()) {{ if (a[i] <= b[j]) r.push_back(a[i++]); else r.push_back(b[j++]); }} while (i < (int)a.size()) r.push_back(a[i++]); while (j < (int)b.size()) r.push_back(b[j++]); return r; }}", "O(n + m)", "O(n + m)", "estimated", ["merge"])
    A("gen3-window", f"positiveWindows_{v}", f"int positiveWindows_{v}(const vector<int>& a, int k) {{ int n = (int)a.size(); long long s = 0; for (int i = 0; i < k; ++i) s += a[i]; int count = s > 0 ? 1 : 0; for (int i = k; i < n; ++i) {{ s += a[i] - a[i - k]; if (s > 0) ++count; }} return count; }}", "O(n)", "O(1)", "estimated", ["window"])
    A("gen3-window", f"rotateArraySteps_{v}", f"void rotateArraySteps_{v}(vector<int>& a, int k) {{ int n = a.size(); if (n == 0) return; for (int r = 0; r < k; ++r) {{ int last = a[n - 1]; for (int i = n - 1; i > 0; --i) a[i] = a[i - 1]; a[0] = last; }} }}", "O(n k)", "O(1)", "exact", ["rotation"])
    A("gen3-window", f"threeWayPartition_{v}", f"void threeWayPartition_{v}(vector<int>& a, int pivot) {{ int lo = 0, i = 0, hi = (int)a.size() - 1; while (i <= hi) {{ if (a[i] < pivot) {{ int tmp = a[lo]; a[lo] = a[i]; a[i] = tmp; ++lo; ++i; }} else if (a[i] > pivot) {{ int tmp = a[i]; a[i] = a[hi]; a[hi] = tmp; --hi; }} else ++i; }} }}", "O(n)", "O(1)", "exact", ["two-pointers"])

# ------------------------------------------------------------------ binary search
for v in range(NV):
    A("gen3-bsearch", f"binSearchIter_{v}", f"int binSearchIter_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size() - 1; while (lo <= hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] == t) return mid; if (a[mid] < t) lo = mid + 1; else hi = mid - 1; }} return -1; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"lowerBoundIdx_{v}", f"int lowerBoundIdx_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size(); while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] < t) lo = mid + 1; else hi = mid; }} return lo; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"upperBoundIdx_{v}", f"int upperBoundIdx_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size(); while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] <= t) lo = mid + 1; else hi = mid; }} return lo; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"binarySearchRec_{v}", f"int binarySearchRec_{v}(const vector<int>& a, int lo, int hi, int t) {{ if (lo > hi) return -1; int mid = lo + (hi - lo) / 2; if (a[mid] == t) return mid; if (a[mid] < t) return binarySearchRec_{v}(a, mid + 1, hi, t); return binarySearchRec_{v}(a, lo, mid - 1, t); }}", "O(log n)", "O(log n)", "exact", ["binary-search", "recursion"])
    A("gen3-bsearch", f"countOccurrences_{v}", f"int countOccurrences_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size(); while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] < t) lo = mid + 1; else hi = mid; }} int first = lo; lo = 0; hi = (int)a.size(); while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] <= t) lo = mid + 1; else hi = mid; }} return lo - first; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"floorSqrtBS_{v}", f"long long floorSqrtBS_{v}(long long n) {{ if (n < 2) return n; long long lo = 1, hi = n, ans = 0; while (lo <= hi) {{ long long mid = (lo + hi) / 2; if (mid * mid <= n) {{ ans = mid; lo = mid + 1; }} else hi = mid - 1; }} return ans; }}", "O(log n)", "O(1)", "exact", ["binary-search", "math"])
    A("gen3-bsearch", f"peakIndex_{v}", f"int peakIndex_{v}(const vector<int>& a) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] < a[mid + 1]) lo = mid + 1; else hi = mid; }} return lo; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"searchRotated_{v}", f"int searchRotated_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size() - 1; while (lo <= hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] == t) return mid; if (a[lo] <= a[mid]) {{ if (a[lo] <= t && t < a[mid]) hi = mid - 1; else lo = mid + 1; }} else {{ if (a[mid] < t && t <= a[hi]) lo = mid + 1; else hi = mid - 1; }} }} return -1; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"findMinRotated_{v}", f"int findMinRotated_{v}(const vector<int>& a) {{ int lo = 0, hi = (int)a.size() - 1; while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] > a[hi]) lo = mid + 1; else hi = mid; }} return a[lo]; }}", "O(log n)", "O(1)", "exact", ["binary-search"])
    A("gen3-bsearch", f"searchInsert_{v}", f"int searchInsert_{v}(const vector<int>& a, int t) {{ int lo = 0, hi = (int)a.size(); while (lo < hi) {{ int mid = lo + (hi - lo) / 2; if (a[mid] < t) lo = mid + 1; else hi = mid; }} return lo; }}", "O(log n)", "O(1)", "exact", ["binary-search"])

# ------------------------------------------------------------------ number theory
for v in range(NV):
    A("gen3-num3", f"gcdEuclid_{v}", f"long long gcdEuclid_{v}(long long a, long long b) {{ while (b != 0) {{ long long t = a % b; a = b; b = t; }} return a; }}", "O(log n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"lcmEuclid_{v}", f"long long lcmEuclid_{v}(long long a, long long b) {{ long long x = a, y = b; while (y != 0) {{ long long t = x % y; x = y; y = t; }} return a / x * b; }}", "O(log n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"isPrimeTrial_{v}", f"bool isPrimeTrial_{v}(long long n) {{ if (n < 2) return false; for (long long i = 2; i * i <= n; ++i) if (n % i == 0) return false; return true; }}", "O(sqrt n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"divisorCount_{v}", f"int divisorCount_{v}(long long n) {{ int cnt = 0; for (long long i = 1; i * i <= n; ++i) if (n % i == 0) cnt += (i * i == n) ? 1 : 2; return cnt; }}", "O(sqrt n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"divisorSum_{v}", f"long long divisorSum_{v}(long long n) {{ long long s = 0; for (long long i = 1; i * i <= n; ++i) if (n % i == 0) {{ s += i; if (i * i != n) s += n / i; }} return s; }}", "O(sqrt n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"modPow_{v}", f"long long modPow_{v}(long long b, long long e, long long m) {{ long long r = 1; b %= m; while (e > 0) {{ if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }} return r; }}", "O(log n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"modInverse_{v}", f"long long modInverse_{v}(long long b, long long m) {{ long long e = m - 2, r = 1; b %= m; while (e > 0) {{ if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }} return r; }}", "O(log n)", "O(1)", "exact", ["math"])
    A("gen3-num3", f"digitSumX_{v}", f"int digitSumX_{v}(int x) {{ int s = 0; while (x) {{ s += x % 10; x /= 10; }} return s; }}", "O(log x)", "O(1)", "exact", ["digits"])
    A("gen3-num3", f"digitCountX_{v}", f"int digitCountX_{v}(int x) {{ int c = 0; while (x) {{ ++c; x /= 10; }} return c; }}", "O(log x)", "O(1)", "exact", ["digits"])
    A("gen3-num3", f"reverseNumberX_{v}", f"int reverseNumberX_{v}(int x) {{ int r = 0; while (x) {{ r = r * 10 + x % 10; x /= 10; }} return r; }}", "O(log x)", "O(1)", "exact", ["digits"])
    A("gen3-num3", f"binaryDigitCount_{v}", f"int binaryDigitCount_{v}(int x) {{ int c = 0; while (x) {{ ++c; x >>= 1; }} return c; }}", "O(log x)", "O(1)", "exact", ["digits"])
    A("gen3-num3", f"digitSquareSum_{v}", f"int digitSquareSum_{v}(int x) {{ int s = 0; while (x) {{ int d = x % 10; s += d * d; x /= 10; }} return s; }}", "O(log x)", "O(1)", "exact", ["digits"])

# ------------------------------------------------------------------ dynamic programming
for v in range(NV):
    A("gen3-dp3", f"fibDP_{v}", f"long long fibDP_{v}(int n) {{ vector<long long> dp(n + 1, 0); if (n >= 1) dp[1] = 1; for (int i = 2; i <= n; ++i) dp[i] = dp[i - 1] + dp[i - 2]; return dp[n]; }}", "O(n)", "O(n)", "exact", ["dp"])
    A("gen3-dp3", f"fibTwoVars_{v}", f"long long fibTwoVars_{v}(int n) {{ if (n <= 1) return n; long long a = 0, b = 1; for (int i = 2; i <= n; ++i) {{ long long c = a + b; a = b; b = c; }} return b; }}", "O(n)", "O(1)", "exact", ["dp"])
    A("gen3-dp3", f"climbStairs_{v}", f"long long climbStairs_{v}(int n) {{ vector<long long> dp(n + 2, 0); dp[0] = 1; for (int i = 0; i <= n; ++i) {{ dp[i + 1] += dp[i]; if (i + 2 <= n + 1) dp[i + 2] += dp[i]; }} return dp[n]; }}", "O(n)", "O(n)", "exact", ["dp"])
    A("gen3-dp3", f"houseRobber_{v}", f"long long houseRobber_{v}(const vector<int>& a) {{ long long take = 0, skip = 0; for (int x : a) {{ long long next = skip + x; if (take > skip) skip = take; take = next; if (take < skip) take = skip; }} return take > skip ? take : skip; }}", "O(n)", "O(1)", "exact", ["dp"])
    A("gen3-dp3", f"kadaneMax_{v}", f"long long kadaneMax_{v}(const vector<int>& a) {{ long long best = a[0], cur = a[0]; for (int i = 1; i < (int)a.size(); ++i) {{ cur += a[i]; if (cur < a[i]) cur = a[i]; if (cur > best) best = cur; }} return best; }}", "O(n)", "O(1)", "exact", ["dp"])
    A("gen3-dp3", f"lisNLogN_{v}", f"int lisNLogN_{v}(const vector<int>& a) {{ vector<int> tails; for (int x : a) {{ auto it = lower_bound(tails.begin(), tails.end(), x); if (it == tails.end()) tails.push_back(x); else *it = x; }} return tails.size(); }}", "O(n log n)", "O(n)", "exact", ["dp", "binary-search"])
    A("gen3-dp3", f"knapsack01_{v}", f"int knapsack01_{v}(const vector<int>& w, const vector<int>& val, int W) {{ vector<int> dp(W + 1, 0); for (int i = 0; i < (int)w.size(); ++i) for (int c = W; c >= w[i]; --c) {{ int cand = dp[c - w[i]] + val[i]; if (cand > dp[c]) dp[c] = cand; }} return dp[W]; }}", "O(n W)", "O(W)", "exact", ["dp"])
    A("gen3-dp3", f"coinChangeMin_{v}", f"int coinChangeMin_{v}(const vector<int>& coins, int amount) {{ vector<int> dp(amount + 1, amount + 1); dp[0] = 0; for (int i = 1; i <= amount; ++i) for (int c : coins) if (c <= i) dp[i] = min(dp[i], dp[i - c] + 1); return dp[amount] > amount ? -1 : dp[amount]; }}", "O(|coins| \u00b7 amount)", "O(amount)", "exact", ["dp"])
    A("gen3-dp3", f"coinChangeWays_{v}", f"int coinChangeWays_{v}(const vector<int>& coins, int amount) {{ vector<int> dp(amount + 1, 0); dp[0] = 1; for (int c : coins) for (int i = c; i <= amount; ++i) {{ int cand = dp[i] + dp[i - c]; dp[i] = cand; }} return dp[amount]; }}", "O(|coins| \u00b7 amount)", "O(amount)", "exact", ["dp"])
    A("gen3-dp3", f"lcsStrings_{v}", f"int lcsStrings_{v}(const string& a, const string& b) {{ int m = a.size(), n = b.size(); vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); for (int i = 1; i <= m; ++i) for (int j = 1; j <= n; ++j) {{ if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1; else dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]; }} return dp[m][n]; }}", "O(n m)", "O(n m)", "exact", ["dp"])
    A("gen3-dp3", f"editDistance_{v}", f"int editDistance_{v}(const string& a, const string& b) {{ int m = a.size(), n = b.size(); vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); for (int i = 0; i <= m; ++i) dp[i][0] = i; for (int j = 0; j <= n; ++j) dp[0][j] = j; for (int i = 1; i <= m; ++i) for (int j = 1; j <= n; ++j) {{ int best = dp[i - 1][j] < dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]; int diag = dp[i - 1][j - 1]; if (a[i - 1] != b[j - 1]) ++diag; if (diag < best) best = diag; dp[i][j] = best; }} return dp[m][n]; }}", "O(n m)", "O(n m)", "exact", ["dp"])
    A("gen3-dp3", f"minPathSum_{v}", f"int minPathSum_{v}(const vector<vector<int>>& g) {{ int n = g.size(), m = g[0].size(); vector<vector<int>> dp(n, vector<int>(m, 0)); dp[0][0] = g[0][0]; for (int i = 1; i < n; ++i) dp[i][0] = dp[i - 1][0] + g[i][0]; for (int j = 1; j < m; ++j) dp[0][j] = dp[0][j - 1] + g[0][j]; for (int i = 1; i < n; ++i) for (int j = 1; j < m; ++j) dp[i][j] = (dp[i - 1][j] < dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1]) + g[i][j]; return dp[n - 1][m - 1]; }}", "O(n m)", "O(n m)", "exact", ["dp", "grid"])
    A("gen3-dp3", f"uniquePaths_{v}", f"long long uniquePaths_{v}(int n, int m) {{ vector<vector<long long>> dp(n, vector<long long>(m, 1)); for (int i = 1; i < n; ++i) for (int j = 1; j < m; ++j) dp[i][j] = dp[i - 1][j] + dp[i][j - 1]; return dp[n - 1][m - 1]; }}", "O(n m)", "O(n m)", "exact", ["dp"])

# ------------------------------------------------------------------ graphs (V, E)
for v in range(NV):
    A("gen3-graph3", f"bfsDistance_{v}", f"int bfsDistance_{v}(const vector<vector<int>>& adj, int src) {{ int V = adj.size(); vector<int> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) {{ int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) {{ dist[v2] = dist[u] + 1; q.push(v2); }} }} int mx = 0; for (int i = 0; i < V; ++i) if (dist[i] > mx) mx = dist[i]; return mx; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"reachableCount_{v}", f"int reachableCount_{v}(const vector<vector<int>>& adj, int src) {{ int V = adj.size(), cnt = 0; vector<bool> seen(V, false); queue<int> q; seen[src] = true; q.push(src); while (!q.empty()) {{ int u = q.front(); q.pop(); ++cnt; for (int v2 : adj[u]) if (!seen[v2]) {{ seen[v2] = true; q.push(v2); }} }} return cnt; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"hasPathBfs_{v}", f"bool hasPathBfs_{v}(const vector<vector<int>>& adj, int src, int dst) {{ int V = adj.size(); vector<bool> seen(V, false); queue<int> q; seen[src] = true; q.push(src); while (!q.empty()) {{ int u = q.front(); q.pop(); if (u == dst) return true; for (int v2 : adj[u]) if (!seen[v2]) {{ seen[v2] = true; q.push(v2); }} }} return false; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"countComponents_{v}", f"int countComponents_{v}(const vector<vector<int>>& adj) {{ int V = adj.size(), comps = 0; vector<bool> seen(V, false); for (int s = 0; s < V; ++s) {{ if (seen[s]) continue; ++comps; queue<int> q; seen[s] = true; q.push(s); while (!q.empty()) {{ int u = q.front(); q.pop(); for (int v2 : adj[u]) if (!seen[v2]) {{ seen[v2] = true; q.push(v2); }} }} }} return comps; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"sumDistancesBfs_{v}", f"long long sumDistancesBfs_{v}(const vector<vector<int>>& adj, int src) {{ int V = adj.size(); vector<long long> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) {{ int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) {{ dist[v2] = dist[u] + 1; q.push(v2); }} }} long long total = 0; for (int i = 0; i < V; ++i) total += dist[i]; return total; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"farthestNodeBfs_{v}", f"int farthestNodeBfs_{v}(const vector<vector<int>>& adj, int src) {{ int V = adj.size(); vector<int> dist(V, -1); queue<int> q; dist[src] = 0; q.push(src); while (!q.empty()) {{ int u = q.front(); q.pop(); for (int v2 : adj[u]) if (dist[v2] == -1) {{ dist[v2] = dist[u] + 1; q.push(v2); }} }} int best = src, mx = 0; for (int i = 0; i < V; ++i) if (dist[i] > mx) {{ mx = dist[i]; best = i; }} return best; }}", "O(V + E)", "O(V)", "estimated", ["graph"])
    A("gen3-graph3", f"degreeSum_{v}", f"long long degreeSum_{v}(const vector<vector<int>>& adj) {{ long long s = 0; for (int u = 0; u < (int)adj.size(); ++u) s += adj[u].size(); return s; }}", "O(V)", "O(1)", "exact", ["graph"])
    A("gen3-graph3", f"topoKahn_{v}", f"vector<int> topoKahn_{v}(const vector<vector<int>>& adj) {{ int V = adj.size(); vector<int> indeg(V, 0); for (int u = 0; u < V; ++u) for (int v2 : adj[u]) ++indeg[v2]; queue<int> q; for (int u = 0; u < V; ++u) if (indeg[u] == 0) q.push(u); vector<int> order; while (!q.empty()) {{ int u = q.front(); q.pop(); order.push_back(u); for (int v2 : adj[u]) {{ --indeg[v2]; if (indeg[v2] == 0) q.push(v2); }} }} return order; }}", "O(V + E)", "O(V)", "estimated", ["graph"])

